import raw from '../../data/embeddings-small.json';
import type { SceneRole } from '../palette';
import { angleDeg } from './cosine-similarity.math';

/**
 * The real embeddings of lesson 1.7, typed and split for the widgets. Generated by notebooks/build/embeddings.py
 * from pinned public models (GloVe 6B 300d for words, snowflake-arctic-embed-xs for texts, Qwen3-1.7B's config and
 * tokenizer for the LLM table facts); the file's `provenance` block records sources, licences, revisions and the
 * rounding error. Nothing here is typed by hand. Three-free and DOM-free (the pure tests import it).
 */

export interface Word {
	word: string;
	group: string;
	/** Row of the word in GloVe's 400 001-row table (row 0 = padding; row i = i-th most frequent word). */
	row: number;
	/** The 300 numbers of the word, rounded to 3 decimals. */
	v: number[];
	/** Display-only 3D projection (absent for the sentence words). */
	pca?: number[];
}

interface Hit {
	word: string;
	cos: number;
}

interface Analogy {
	a: string;
	b: string;
	c: string;
	full_vocab_top: Hit[];
	full_vocab_top_with_inputs: Hit[];
}

interface Data {
	provenance: {
		words: { table_rows: number; dims: number; decimals: number; max_cos_rounding_error: number; model: string; file: string; license: string };
		texts: { model: string; revision: string; license: string; dims: number };
		pca: { explained: number[]; origin: number[] };
	};
	words: Word[];
	full_vocab_neighbours: Record<string, Hit[]>;
	analogies: Analogy[];
	sentence: string[];
	llm: { model: string; rows: number; dims: number; text: string; tokens: { piece: string; id: number }[] };
	search: { docs: { text: string; v: number[] }[]; queries: { text: string; v: number[] }[] };
}

const data = raw as Data;

export const PROV = data.provenance;

/** Words of the heatmap, neighbour list, analogies and the 3D view (the four sentence words are kept apart). */
export const WORDS: readonly Word[] = data.words.filter((w) => w.group !== 'sentence');
export const VECS: readonly number[][] = WORDS.map((w) => w.v);

/** Groups in table order, each with its scene colour (legend and points share it). */
export const GROUPS = ['animals', 'vehicles', 'people', 'places', 'food', 'graphics', 'qualities'] as const;
export type Group = (typeof GROUPS)[number];
export const GROUP_ROLE: Readonly<Record<Group, SceneRole>> = {
	animals: 'vecA', vehicles: 'vecB', people: 'vecC', places: 'axisX', food: 'light', graphics: 'axisY', qualities: 'ink',
};

/** Every word of the file (including the sentence words) by spelling. */
const BY_WORD = new Map(data.words.map((w) => [w.word, w]));
export function word(w: string): Word {
	const hit = BY_WORD.get(w);
	if (!hit) throw new Error(`embeddings: no word "${w}"`);
	return hit;
}
export const indexOf = (w: string): number => {
	const i = WORDS.findIndex((x) => x.word === w);
	if (i < 0) throw new Error(`embeddings: "${w}" is not a table word`);
	return i;
};

/** The attention-preview sentence, word by word, with each word's row of the table. */
export const SENTENCE: readonly Word[] = data.sentence.map(word);

export const ANALOGIES: readonly Analogy[] = data.analogies;
export const NEIGHBOURS = data.full_vocab_neighbours;
export const LLM = data.llm;
export const DOCS = data.search.docs;
export const QUERIES = data.search.queries;

// ---------------------------------------------------------------------------------------------------------------
// The display projection (COS-3).

/** Half-size of the COS-3 view; the projected coordinates (in [−1, 1]) are scaled to it. */
export const PIC = 3;

/** The two table rows the heatmap selected (store key `pair`), checked: a bad index is an authoring error. */
export function pairOf(v: Readonly<Record<string, number | readonly number[]>>): [number, number] {
	const p = v.pair as readonly number[];
	const ok = (i: number) => Number.isInteger(i) && i >= 0 && i < WORDS.length;
	if (!Array.isArray(p) || p.length !== 2 || !ok(p[0]) || !ok(p[1])) throw new Error(`cosine-similarity: bad pair ${String(p)}`);
	return [p[0], p[1]];
}

/** Projected position of a table word in the COS-3 view. */
export const picPos = (i: number): number[] => WORDS[i].pca!.map((x) => x * PIC);
/** Where the zero vector lands in the view: the drawn arrows start here, so they are projections of the real arrows. */
export const PIC_ORIGIN: readonly number[] = PROV.pca.origin.map((x) => x * PIC);

/** The selected pair as drawn: the two projected arrows and the angle between them IN THE PICTURE. */
export function picture([i, j]: readonly [number, number]) {
	const a = picPos(i), b = picPos(j);
	const da = a.map((x, k) => x - PIC_ORIGIN[k]), db = b.map((x, k) => x - PIC_ORIGIN[k]);
	return { a, b, da, db, th: angleDeg(da, db) };
}
